package com.acme.school.enrolment;

/**
 * Enforces that a pupil can only be placed in a class matching their year group.
 */
public class YearGroupMatchGuard {

    private final PupilRepository pupils;
    private final ClassRepository classes;

    public YearGroupMatchGuard(PupilRepository pupils, ClassRepository classes) {
        this.pupils = pupils;
        this.classes = classes;
    }

    public void assertMatch(String pupilId, String classId) {
        Pupil pupil = pupils.require(pupilId);
        SchoolClass sc = classes.require(classId);
        if (pupil.getYearGroup() != sc.getYearGroup()) {
            throw new YearGroupMismatchException(pupilId, classId,
                pupil.getYearGroup(), sc.getYearGroup());
        }
    }
}

class YearGroupMismatchException extends RuntimeException {
    public YearGroupMismatchException(String p, String c, int pg, int cg) {
        super("Pupil " + p + " in year " + pg + " cannot join class " + c + " in year " + cg);
    }
}

