package com.acme.school.attendance;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Computes attendance percentage for a pupil over a term.
 */
public class AttendancePercentageCalculator {

    private final AttendanceRepository attendance;
    private final TimetableRepository timetable;

    public AttendancePercentageCalculator(AttendanceRepository attendance, TimetableRepository timetable) {
        this.attendance = attendance;
        this.timetable = timetable;
    }

    public BigDecimal percentageFor(String pupilId, String term) {
        long scheduled = timetable.sessionsCount(pupilId, term);
        if (scheduled == 0) {
            return BigDecimal.ZERO;
        }
        long attended = attendance.sessionsAttended(pupilId, term);
        return BigDecimal.valueOf(attended)
            .multiply(BigDecimal.valueOf(100))
            .divide(BigDecimal.valueOf(scheduled), 2, RoundingMode.HALF_UP);
    }
}

