/** Computes punctuality rate: on-time arrivals vs total arrivals. */
public class PunctualityRateCalculator {
    private final AttendanceRepository attendance;

    public PunctualityRateCalculator(AttendanceRepository attendance) {
        this.attendance = attendance;
    }

    public BigDecimal rate(String pupilId, String term) {
        long total = attendance.totalArrivals(pupilId, term);
        if (total == 0) return BigDecimal.ZERO;
        long onTime = attendance.onTimeArrivals(pupilId, term);
        return BigDecimal.valueOf(onTime * 100.0 / total);
    }
