package com.acme.school.pupils;

import java.time.LocalDate;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Creates a pupil after validating inputs and issuing a unique reference.
 */
@RestController
public class PupilRegistrationController {

    private final PupilRepository pupils;
    private final PupilReferenceGenerator references;

    public PupilRegistrationController(PupilRepository pupils, PupilReferenceGenerator references) {
        this.pupils = pupils;
        this.references = references;
    }

    @PostMapping("/pupils")
    public PupilView register(@RequestBody PupilRegistrationRequest req) {
        if (req.getGivenName() == null || req.getGivenName().isBlank()) {
            throw new IllegalArgumentException("Given name is required");
        }
        if (req.getFamilyName() == null || req.getFamilyName().isBlank()) {
            throw new IllegalArgumentException("Family name is required");
        }
        if (req.getDateOfBirth() == null || req.getDateOfBirth().isAfter(LocalDate.now())) {
            throw new IllegalArgumentException("A valid date of birth is required");
        }
        Pupil p = new Pupil();
        p.setReference(references.next());
        p.setGivenName(req.getGivenName());
        p.setFamilyName(req.getFamilyName());
        p.setDateOfBirth(req.getDateOfBirth());
        p.setYearGroup(req.getYearGroup());
        return PupilView.from(pupils.save(p));
    }
}

