package com.acme.school.attendance;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;

/**
 * Builds and saves a class register for a date.
 */
public class ClassRegisterService {

    private final EnrolmentRepository enrolments;
    private final RegisterRepository registers;

    public ClassRegisterService(EnrolmentRepository enrolments, RegisterRepository registers) {
        this.enrolments = enrolments;
        this.registers = registers;
    }

    public RegisterView open(String classId, LocalDate date) {
        List<Pupil> roll = enrolments.pupilsOnRoll(classId);
        Map<String, RegisterMark> existing = registers.marksFor(classId, date);
        return new RegisterView(classId, date, roll, existing);
    }

    public void save(String classId, LocalDate date, Map<String, AttendanceCode> marks) {
        for (Map.Entry<String, AttendanceCode> e : marks.entrySet()) {
            registers.upsert(classId, date, e.getKey(), e.getValue());
        }
    }
}

