package com.acme.school.security;

import org.springframework.security.access.AccessDeniedException;

/**
 * Authorises edits to a pupil record.
 */
public class PupilRecordEditPolicy {

    private final PupilRepository pupils;
    private final ClassRepository classes;
    private final StaffDirectory staff;

    public PupilRecordEditPolicy(PupilRepository pupils, ClassRepository classes, StaffDirectory staff) {
        this.pupils = pupils;
        this.classes = classes;
        this.staff = staff;
    }

    public void assertMayEdit(String userId, String pupilId) {
        Pupil p = pupils.require(pupilId);
        if (staff.hasRole(userId, "OFFICE")) {
            return;
        }
        SchoolClass c = classes.require(p.getCurrentClassId());
        if (userId.equals(c.getFormTutorId())) {
            return;
        }
        throw new AccessDeniedException("Pupil " + pupilId + " may not be edited by " + userId);
    }
}

