package com.acme.school.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an audit row for each attendance mark change.
 */
public class AttendanceChangeAuditor {

    private final EntityManager em;

    public AttendanceChangeAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String pupilId, String classId, java.time.LocalDate date,
                       String oldMark, String newMark, String userId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            AttendanceAudit a = new AttendanceAudit();
            a.setPupilId(pupilId);
            a.setClassId(classId);
            a.setRegisterDate(date);
            a.setOldMark(oldMark);
            a.setNewMark(newMark);
            a.setUserId(userId);
            a.setOccurredAt(Instant.now());
            em.persist(a);
            tx.commit();
        } catch (RuntimeException e) {
            tx.rollback();
            throw e;
        }
    }
}

