/* daily_absence_report.c - write unauthorised absence report as CSV */
#include <stdio.h>
#include "school_db.h"

int write_absence_report(const char *date, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "pupil_ref,name,class_code,guardian_phone\n");

    db_cursor_t *cur = NULL;
    if (db_open_unauthorised_absence_cursor(&cur, date) != DB_OK) { fclose(out); return -2; }

    absence_row_t row;
    int rows = 0;
    while (db_absence_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%s %s,%s,%s\n",
                row.pupil_ref, row.given_name, row.family_name,
                row.class_code, row.guardian_phone ? row.guardian_phone : "");
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

